import fs from 'node:fs';
const root = 'D:/2026 - Tuan/danang-vite/';
const rd = p => fs.readFileSync(root + p, 'utf8').replace(/\r\n/g, '\n');
const wr = (p, s) => fs.writeFileSync(root + p, s.replace(/\n/g, '\r\n'));
function rep(s, a, b) { if (!s.includes(a)) throw new Error('thiếu: ' + a.slice(0, 60)); if (s.split(a).length > 2) throw new Error('trùng: ' + a.slice(0, 60)); return s.replace(a, () => b); }

/* ---- decisions.md ---- */
let d = rd('.github/memory-bank/decisions.md');
d = d.replace(/\n*$/, '\n') + `
## D-029: Đi dạo là chế độ \`stroll\` dùng chung Durable Object \`sky\` với dù lượn, va chạm tính ở máy khách bằng bản đồ 2D thuần — 2026-11-11 — Chấp nhận
Bối cảnh: thêm cách ngắm từ mặt đất (camera sau lưng, đi / chạy / nhảy / chụp ảnh) trên Cầu Rồng, Cầu sông Hàn, hai bờ sông và Cầu Tình Yêu, thấy người đi dạo khác và người bay dù, mà không tăng draw call ở góc nhìn cũ và không đổi chuỗi \`rand()\`. Tên \`walk\` đã là góc nhìn mắt người (\`views/camera.ts\`) nên chế độ mới là \`stroll\`. [spec](../../docs/superpowers/specs/2026-11-11-di-dao-design.md) · [plan](../../docs/superpowers/plans/2026-11-11-di-dao.md)
Quyết định: \`src/explore/stroll/\`, thông số \`CONFIG.stroll\`, tiền tố \`st*\`. Máy chủ: cùng Durable Object \`sky\`, thêm 5 slot đi dạo bên cạnh 5 slot bay (\`server/multi/\`, \`multiParams.stroll\`); tin vị trí đi dạo có thêm dáng \`w\` (đứng / đi / chạy / nhảy / chụp), không góc nghiêng; khách dù cũ bỏ qua người đi dạo, khách mới gặp Worker cũ thì đi một mình (\`stOffline\`) nên thứ tự deploy không quan trọng. Va chạm là bản đồ lưới thuần (\`map.ts\`, ô 16 m, không import three / CONFIG) dựng từ vùng đi được + vật cản (\`mapData.ts\`, \`sceneData.ts\`); tường cao chặn, tường thấp (≤ \`lowMax\` 1,0 m) nhảy qua được, bậc ≤ \`stepMax\` 0,35 m tự bước, kẹt thì \`stNearestValid\`. Nhân vật dùng hình người có sẵn (\`common/people\`, thêm cờ \`PP_FLAG.jump\` và dáng nhảy trong shader), một InstancedMesh \`stroll-people\` chỉ dựng khi vào chế độ (+1 lệnh vẽ trong chế độ, 0 ở góc cũ). Đi dạo của người này hiện ở người kia qua \`remote.ts\` / \`interp.ts\` / \`labels.ts\` mở rộng; người thứ 6 xem bám một người, có lời mời khi có chỗ; nhịp quay Cầu sông Hàn đóng / mở không đồng bộ giữa máy (sơ tán khi cầu mở, như dù lượn). Chụp ảnh: đọc canvas ngay sau một lần vẽ (\`afterRender\`), PNG, điện thoại chia sẻ, lỗi thì tải về; thông báo ảnh ở \`#stToast\` riêng, không dùng \`#exMpNotice\`. Cảm ứng: cần gạt ảo + nút Nhảy + 📷 tự viết bằng pointer events. \`?explore=glider\` vẫn bay một mình, không qua slot. Dòng hướng dẫn trên máy tính là \`#stHint\` (anh em của \`#exHint\`); phím theo vị trí (\`e.code\`) để bàn phím không Latin vẫn đi được.
Hệ quả: bản đồ va chạm có oracle độc lập trong test (\`tests/stroll-unit/\`, \`tests/stroll-check.mjs\`: tia raycast lên mesh có tên + so từng bước với hộp tòa nhà, kiểm không vacuous), không dùng chính \`map.ts\` để chấm \`map.ts\`. Để vùng bờ không xuyên lan can dải dạo, vùng bờ thụt vào ngoài lan can (|x| 263,49 = lan can 263,14 + bán kính) và \`promenade.ts\` chừa một khe lan can ở lối vào Cầu Tình Yêu (\`CONFIG.riverfront.love.railGap\`; không có \`rnd()\`, cùng mesh gộp nên draw call giữ nguyên); đổi lan can dải dạo thì phải sửa \`tests/stroll-unit/mapData.test.ts\` (đang chép bố cục lan can). Danh sách người bay dù đổi tiêu đề thành "Đi dạo n/5 · Bay n/5" (thay đổi nhìn thấy được của giao diện D-024). Worker \`danang-sky\` trên Cloudflare vẫn là bản cũ: tới khi \`npm --prefix server/multi run deploy\` (cần người dùng đồng ý), bấm Đi dạo trên trang công khai hiện thông báo ngoại tuyến và đi một mình (đúng thiết kế). Camera chỉ đi trong vùng đi được nên ở mép cầu nhìn vào trong thì camera chui lên trên đầu nhân vật, và ở dải phân cách Cầu Rồng có thể lọt vào thân rồng (hoãn, chờ người dùng thử demo). Chưa đo draw call, FPS GPU / điện thoại thật.
`;
wr('.github/memory-bank/decisions.md', d);

